use thiserror::Error;
use zip::result::ZipError;

#[derive(Error, Debug)]
pub enum FinderError {
    #[error("standard I/O error - {e}")]
    StdIoError { e: std::io::Error },
    #[error("Invalid zip file error - {message}")]
    InvalidZip { message: String },
    #[error("CLI argument error - {message:?}")]
    CliArgumentError { message: String },
    #[error("CLI argument error ({e})")]
    ClapError { e: clap::Error },
    #[error("CLI argument match error ({message})")]
    ClapMatchError { message: String },
}

impl FinderError {
    pub const fn invalid_zip_error(message: String) -> Self {
        InvalidZip { message }
    }
}

impl From<std::io::Error> for FinderError {
    fn from(e: std::io::Error) -> Self {
        Self::StdIoError { e }
    }
}

impl From<ZipError> for FinderError {
    fn from(e: ZipError) -> Self {
        InvalidZip {
            message: format!("{e}"),
        }
    }
}

impl From<clap::Error> for FinderError {
    fn from(e: clap::Error) -> Self {
        Self::ClapError { e }
    }
}

impl From<clap::parser::MatchesError> for FinderError {
    fn from(e: clap::parser::MatchesError) -> Self {
        ClapMatchError {
            message: format!("{e}"),
        }
    }
}
"}

{"exit_code":0,"stderr":"","stdout":"use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::PathBuf;

pub fn password_reader_count(file_path: PathBuf) -> Result<usize, std::io::Error> {
    // compute the number of lines in the file
    let file = File::open(file_path)?;
    let mut reader = BufReader::new(file);
    let mut total_password_count = 0;
    let mut line_buffer = Vec::new();
    loop {
        // count line number without reallocating each line
        // read_until to avoid UTF-8 validation (unlike read_line which produce a String)
        let res = reader.read_until(b'\n', &mut line_buffer)?;
        if res == 0 {
            // end of file
            break;
        }
        line_buffer.clear();
        total_password_count += 1;
    }
    Ok(total_password_count)
}

pub fn password_dictionary_reader_iter(file_path: PathBuf) -> impl Iterator<Item = Vec<u8>> {
    DictionaryReader::new(file_path)
}

struct DictionaryReader {
    reader: BufReader<File>,
    line_buffer: Vec<u8>,
}

impl DictionaryReader {
    pub fn new(file_path: PathBuf) -> Self {
        let file = File::open(file_path).expect("Unable to open file");
        let reader = BufReader::new(file);
        Self {
            reader,
            line_buffer: Vec::new(),
        }
    }
}

impl Iterator for DictionaryReader {
    type Item = Vec<u8>;

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            self.line_buffer.clear();
            let res = self.reader.read_until(b'\n', &mut self.line_buffer);
            match res {
                Ok(0) => return None,
                Ok(_) => {
                    // cleanup line endings
                    if self.line_buffer.last() == Some(&b'\n') {
                        self.line_buffer.pop();
                        if self.line_buffer.last() == Some(&b'\r') {
                            self.line_buffer.pop();
                        }
                    }
                    return Some(self.line_buffer.clone());
                }
                Err(_) => continue,
            }
        }
    }
}

